#!/usr/bin/env python3
"""Apply required platform permissions to a native scaffold generated by Flutter."""
from pathlib import Path
import plistlib
import re
import xml.etree.ElementTree as ET

root = Path(__file__).resolve().parent.parent

# Android: allow local_auth to host a Fragment and disable auto-backup for
# encrypted data whose Keystore key may NOT be restored on another device.
manifest = root / 'android/app/src/main/AndroidManifest.xml'
if manifest.exists():
    android_ns = 'http://schemas.android.com/apk/res/android'
    ET.register_namespace('android', android_ns)
    tree = ET.parse(manifest)
    node = tree.getroot()
    perms = {p.attrib.get(f'{{{android_ns}}}name') for p in node.findall('uses-permission')}
    for perm in ('android.permission.USE_BIOMETRIC', 'android.permission.USE_FINGERPRINT'):
        if perm not in perms:
            ET.SubElement(node, 'uses-permission', {f'{{{android_ns}}}name': perm})
    application = node.find('application')
    if application is not None:
        application.set(f'{{{android_ns}}}label', 'Savour')
        application.set(f'{{{android_ns}}}allowBackup', 'false')
        application.set(f'{{{android_ns}}}fullBackupContent', 'false')
    tree.write(manifest, encoding='utf-8', xml_declaration=True)

# AppCompat is required by the biometric prompt on Android 7/8. Flutter's
# default launch theme inherits from a platform Theme instead.
for style_file in root.glob('android/app/src/main/res/values*/styles.xml'):
    styles = ET.parse(style_file)
    for style in styles.getroot().findall('style'):
        if style.attrib.get('name') in ('LaunchTheme', 'NormalTheme'):
            style.set('parent', 'Theme.AppCompat.DayNight.NoActionBar')
    styles.write(style_file, encoding='utf-8', xml_declaration=True)

for activity in root.glob('android/app/src/main/kotlin/**/MainActivity.kt'):
    code = activity.read_text()
    code = code.replace('import io.flutter.embedding.android.FlutterActivity',
                        'import io.flutter.embedding.android.FlutterFragmentActivity')
    code = code.replace('class MainActivity : FlutterActivity()',
                        'class MainActivity : FlutterFragmentActivity()')
    activity.write_text(code)

for gradle in (root / 'android/app/build.gradle.kts', root / 'android/app/build.gradle'):
    if gradle.exists():
        code = gradle.read_text()
        code = re.sub(r'minSdk\s*=\s*flutter\.minSdkVersion', 'minSdk = 24', code)
        code = re.sub(r'minSdkVersion\s+flutter\.minSdkVersion', 'minSdkVersion 24', code)
        gradle.write_text(code)

# iOS: permission strings for the image picker and local_auth.
plist_file = root / 'ios/Runner/Info.plist'
if plist_file.exists():
    with plist_file.open('rb') as f:
        plist = plistlib.load(f)
    plist.update({
        'CFBundleDisplayName': 'Savour',
        'NSCameraUsageDescription': 'Take a photo to save in your private food album.',
        'NSPhotoLibraryUsageDescription': 'Choose food photos to store privately in Savour.',
        'NSFaceIDUsageDescription': 'Unlock your private Savour food album.',
        'UIFileSharingEnabled': False,
        'LSSupportsOpeningDocumentsInPlace': False,
    })
    with plist_file.open('wb') as f:
        plistlib.dump(plist, f, sort_keys=False)

podfile = root / 'ios/Podfile'
if podfile.exists():
    text = podfile.read_text()
    text = re.sub(r'^#?\s*platform\s*:ios,\s*[\'\"]\d+\.\d+[\'\"]',
                  "platform :ios, '13.0'", text, count=1, flags=re.MULTILINE)
    podfile.write_text(text)

print('Savour native permissions configured.')
